import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Table, Badge, Tabs, Tab, Alert } from 'react-bootstrap';
import { useParams } from 'react-router-dom';

const PortfolioDetail = () => {
  const { id } = useParams();
  const [portfolio, setPortfolio] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    // For demonstration purposes, we'll use mock data
    const mockPortfolio = {
      id: parseInt(id),
      name: 'Primary Investment Portfolio',
      description: 'Long-term investment portfolio focused on growth stocks and dividends',
      type: 'Equity',
      totalValue: 1245000.75,
      investedValue: 1000000.00,
      unrealizedReturn: 12.5,
      realizedReturn: 8.2,
      lastUpdated: '2025-02-28',
      holdings: [
        {
          id: 1,
          symbol: 'AAPL',
          name: 'Apple Inc.',
          quantity: 100,
          avgCostPrice: 150.25,
          currentPrice: 170.50,
          valueAtCost: 15025.00,
          currentValue: 17050.00,
          unrealizedPL: 2025.00,
          unrealizedPLPercent: 13.48,
          sector: 'Technology',
          allocation: 20.5
        },
        {
          id: 2,
          symbol: 'MSFT',
          name: 'Microsoft Corporation',
          quantity: 50,
          avgCostPrice: 220.75,
          currentPrice: 245.30,
          valueAtCost: 11037.50,
          currentValue: 12265.00,
          unrealizedPL: 1227.50,
          unrealizedPLPercent: 11.12,
          sector: 'Technology',
          allocation: 15.2
        },
        {
          id: 3,
          symbol: 'AMZN',
          name: 'Amazon.com Inc.',
          quantity: 20,
          avgCostPrice: 3100.00,
          currentPrice: 3300.00,
          valueAtCost: 62000.00,
          currentValue: 66000.00,
          unrealizedPL: 4000.00,
          unrealizedPLPercent: 6.45,
          sector: 'Consumer Discretionary',
          allocation: 12.8
        }
      ],
      performanceMetrics: {
        xirr: 14.5,
        sharpeRatio: 1.8,
        volatility: 15.2,
        drawdown: 8.5,
        alpha: 2.3,
        beta: 0.92
      },
      sectorAllocation: [
        { sector: 'Technology', percentage: 42.5 },
        { sector: 'Financial Services', percentage: 18.2 },
        { sector: 'Healthcare', percentage: 12.7 },
        { sector: 'Consumer Discretionary', percentage: 15.6 },
        { sector: 'Industrials', percentage: 7.3 },
        { sector: 'Others', percentage: 3.7 }
      ]
    };

    // Simulate API call
    setTimeout(() => {
      setPortfolio(mockPortfolio);
      setLoading(false);
    }, 1000);

    // In a real application, we would fetch data from an API:
    // fetch(`/api/portfolios/${id}`)
    //   .then(response => {
    //     if (!response.ok) {
    //       throw new Error('Portfolio not found');
    //     }
    //     return response.json();
    //   })
    //   .then(data => {
    //     setPortfolio(data);
    //     setLoading(false);
    //   })
    //   .catch(err => {
    //     setError(err.message);
    //     setLoading(false);
    //   });
  }, [id]);

  if (loading) {
    return (
      <Container>
        <div className="text-center py-5">
          <div className="spinner-border" role="status">
            <span className="visually-hidden">Loading...</span>
          </div>
          <p className="mt-3">Loading portfolio details...</p>
        </div>
      </Container>
    );
  }

  if (error) {
    return (
      <Container>
        <Alert variant="danger">
          {error}
        </Alert>
      </Container>
    );
  }

  if (!portfolio) {
    return (
      <Container>
        <Alert variant="warning">
          Portfolio not found. The requested portfolio may have been deleted or doesn't exist.
        </Alert>
      </Container>
    );
  }

  const getReturnClass = (value) => {
    if (value > 0) return 'text-success';
    if (value < 0) return 'text-danger';
    return 'text-muted';
  };

  return (
    <Container>
      <h1 className="mb-4">{portfolio.name}</h1>

      {portfolio.description && (
        <p className="lead mb-4">{portfolio.description}</p>
      )}

      <Row className="mb-4">
        <Col lg={3} md={6} className="mb-3">
          <Card className="h-100">
            <Card.Body>
              <Card.Title>Total Value</Card.Title>
              <h3 className="mt-3">₹{portfolio.totalValue.toLocaleString('en-IN')}</h3>
              <p className="text-muted mb-0">
                Last updated: {new Date(portfolio.lastUpdated).toLocaleDateString()}
              </p>
            </Card.Body>
          </Card>
        </Col>

        <Col lg={3} md={6} className="mb-3">
          <Card className="h-100">
            <Card.Body>
              <Card.Title>Unrealized Return</Card.Title>
              <h3 className={`mt-3 ${getReturnClass(portfolio.unrealizedReturn)}`}>
                {portfolio.unrealizedReturn > 0 ? '+' : ''}
                {portfolio.unrealizedReturn.toFixed(2)}%
              </h3>
              <p className={`mb-0 ${getReturnClass(portfolio.unrealizedReturn)}`}>
                ₹{(portfolio.totalValue - portfolio.investedValue).toLocaleString('en-IN')}
              </p>
            </Card.Body>
          </Card>
        </Col>

        <Col lg={3} md={6} className="mb-3">
          <Card className="h-100">
            <Card.Body>
              <Card.Title>XIRR</Card.Title>
              <h3 className={`mt-3 ${getReturnClass(portfolio.performanceMetrics.xirr)}`}>
                {portfolio.performanceMetrics.xirr.toFixed(2)}%
              </h3>
              <p className="text-muted mb-0">
                Time-weighted return
              </p>
            </Card.Body>
          </Card>
        </Col>

        <Col lg={3} md={6} className="mb-3">
          <Card className="h-100">
            <Card.Body>
              <Card.Title>Risk Rating</Card.Title>
              <h3 className="mt-3">
                <Badge 
                  bg={
                    portfolio.performanceMetrics.volatility < 10 ? 'success' : 
                    portfolio.performanceMetrics.volatility < 20 ? 'warning' : 'danger'
                  }
                >
                  {portfolio.performanceMetrics.volatility < 10 ? 'Low' : 
                   portfolio.performanceMetrics.volatility < 20 ? 'Moderate' : 'High'}
                </Badge>
              </h3>
              <p className="text-muted mb-0">
                Volatility: {portfolio.performanceMetrics.volatility.toFixed(2)}%
              </p>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      <Tabs className="mb-4">
        <Tab eventKey="holdings" title="Holdings">
          <div className="table-responsive mt-3">
            <Table hover>
              <thead>
                <tr>
                  <th>Symbol</th>
                  <th>Company</th>
                  <th>Quantity</th>
                  <th>Avg. Cost</th>
                  <th>Current Price</th>
                  <th>Current Value</th>
                  <th>Allocation</th>
                  <th>Unrealized P/L</th>
                  <th>P/L %</th>
                </tr>
              </thead>
              <tbody>
                {portfolio.holdings.map(holding => (
                  <tr key={holding.id}>
                    <td>{holding.symbol}</td>
                    <td>{holding.name}</td>
                    <td>{holding.quantity}</td>
                    <td>₹{holding.avgCostPrice.toFixed(2)}</td>
                    <td>₹{holding.currentPrice.toFixed(2)}</td>
                    <td>₹{holding.currentValue.toLocaleString('en-IN')}</td>
                    <td>{holding.allocation.toFixed(2)}%</td>
                    <td className={getReturnClass(holding.unrealizedPL)}>
                      ₹{holding.unrealizedPL.toLocaleString('en-IN')}
                    </td>
                    <td className={getReturnClass(holding.unrealizedPLPercent)}>
                      {holding.unrealizedPLPercent > 0 ? '+' : ''}
                      {holding.unrealizedPLPercent.toFixed(2)}%
                    </td>
                  </tr>
                ))}
              </tbody>
            </Table>
          </div>
        </Tab>

        <Tab eventKey="performance" title="Performance">
          <Row className="mt-3">
            <Col md={6}>
              <Card>
                <Card.Body>
                  <Card.Title>Performance Metrics</Card.Title>
                  <Table>
                    <tbody>
                      <tr>
                        <td><strong>XIRR</strong></td>
                        <td className={getReturnClass(portfolio.performanceMetrics.xirr)}>
                          {portfolio.performanceMetrics.xirr.toFixed(2)}%
                        </td>
                      </tr>
                      <tr>
                        <td><strong>Sharpe Ratio</strong></td>
                        <td>{portfolio.performanceMetrics.sharpeRatio.toFixed(2)}</td>
                      </tr>
                      <tr>
                        <td><strong>Volatility</strong></td>
                        <td>{portfolio.performanceMetrics.volatility.toFixed(2)}%</td>
                      </tr>
                      <tr>
                        <td><strong>Max Drawdown</strong></td>
                        <td className="text-danger">-{portfolio.performanceMetrics.drawdown.toFixed(2)}%</td>
                      </tr>
                      <tr>
                        <td><strong>Alpha</strong></td>
                        <td className={getReturnClass(portfolio.performanceMetrics.alpha)}>
                          {portfolio.performanceMetrics.alpha.toFixed(2)}%
                        </td>
                      </tr>
                      <tr>
                        <td><strong>Beta</strong></td>
                        <td>{portfolio.performanceMetrics.beta.toFixed(2)}</td>
                      </tr>
                    </tbody>
                  </Table>
                </Card.Body>
              </Card>
            </Col>

            <Col md={6}>
              <Card>
                <Card.Body>
                  <Card.Title>Sector Allocation</Card.Title>
                  <Table>
                    <thead>
                      <tr>
                        <th>Sector</th>
                        <th>Allocation</th>
                      </tr>
                    </thead>
                    <tbody>
                      {portfolio.sectorAllocation.map((item, index) => (
                        <tr key={index}>
                          <td>{item.sector}</td>
                          <td>{item.percentage.toFixed(2)}%</td>
                        </tr>
                      ))}
                    </tbody>
                  </Table>
                </Card.Body>
              </Card>
            </Col>
          </Row>
        </Tab>
      </Tabs>
    </Container>
  );
};

export default PortfolioDetail;
